import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;

public class G {
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int s = sc.nextInt() - 1;
        long t = sc.nextLong();

        int[] next = new int[n];
        Arrays.fill(next, -1);

        while (t % n != 0) {
            s = move(s, (int) (t % n), m, n);
            t--;
        }

        long cant = t / n;
        int prev = s;

        while (cant > 0 && next[s] == -1) {
            s = cycleStep(s, m, n);
            next[prev] = s;
            prev = s;
            cant--;
        }

        if (cant > 0) {
            long cycle = 1;
            prev = s;
            while (next[prev] != s) {
                cycle++;
                prev = next[prev];
            }
            long rem = cant % cycle;
            for (long i = 0; i < rem; i++) {
                s = next[s];
            }
        }

        out.println(s + 1);
        out.flush();
    }

    static int move(int s, int x, int m, int n) {
        if (s < m) {
            s += x;
        } else {
            s += n - x;
        }
        return s % n;
    }

    static int cycleStep(int s, int m, int n) {
        for (int i = n - 1; i > 0; i--) {
            if (s < m) {
                s += i;
            } else {
                s += n - i;
            }
            if (s >= n) {
                s -= n;
            }
        }
        return s;
    }

    static class FastScanner {
        private InputStream in = System.in;

        private int read() throws IOException {
            return in.read();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (c != -1 && c <= ' ') {
                c = read();
            }
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
